-- 投票所の位置を登録する（マップ用）
-- Supabase の SQL Editor で、migrations/20261028020000_precinct_location.sql の後に実行する。
--
-- 出典：流山市「投票所所在地データ」（touhyouzyo.20261026.csv、令和8年9月1日時点、CC BY 4.0）
-- https://www.city.nagareyama.chiba.jp/information/1008966/1008982/1008985/1015914.html
--
-- 公開中・下書きの選挙回の投票区に、投票区番号で位置を登録する。

update public.election_precincts ep
set latitude = v.latitude, longitude = v.longitude
from (values
  (1, 35.859312, 139.9046961),
  (2, 35.8562708, 139.9028991),
