  (9, 35.8362895, 139.9517425),
  (10, 35.843178, 139.950006),
  (11, 35.848178, 139.949352),
  (12, 35.8451, 139.94764),
  (13, 35.8437014, 139.9386518),
  (14, 35.8536073, 139.9175284),
  (15, 35.8552712, 139.9278358),
  (16, 35.8596209, 139.9361877),
  (17, 35.860405, 139.944942),
  (18, 35.87599669, 139.9375686),
  (19, 35.8760569, 139.9317542),
