  (28, 35.9086065, 139.908994),
  (29, 35.912341, 139.904644),
  (30, 35.9094174, 139.8993587),
  (31, 35.8957585, 139.8997843),
  (32, 35.890598, 139.901869),
  (33, 35.9063262, 139.9055584),
  (34, 35.891815, 139.916799),
  (35, 35.8475749, 139.8974859),
  (36, 35.839257, 139.895729),
  (37, 35.841451, 139.9109306),
  (38, 35.866722, 139.905886),
  (39, 35.912531, 139.9135878),
  (40, 35.887257, 139.913724),
  (41, 35.8727099, 139.9184),
